        {
            case Channel.Email:
                body = template + message.Body;
                break;
            case Channel.Sms:
                body = message.Body;
                break;
            case Channel.Push:
                body = message.Subject;
                break;
            default:
                body = message.Body;
                break;
        }

        if (attempt > 0 && body.Length > 0)
            return $"retry:{attempt}:{body.Length}";
        if (body.Length == 0)
            return "empty render";
        return $"sent:{body.Length}";
